CREATE TABLE pts AS SELECT i AS i, 'name_' || (i % 7) AS name FROM range(5000) t(i);
COPY (SELECT 'hello model' AS a) TO 'hf://models/lhoestq/playground/duckdb/m1.parquet';
COPY pts TO 'hf://models/lhoestq/playground/duckdb/nested/deep/part-0.parquet' (FORMAT PARQUET, COMPRESSION zstd);
COPY (SELECT 1 AS a, 'x' AS b) TO 'hf://models/lhoestq/playground/duckdb/m1.csv' (FORMAT CSV);
COPY (SELECT 'json' AS k) TO 'hf://models/lhoestq/playground/duckdb/m1.json';
COPY (SELECT 'git tracked text' AS t) TO 'hf://models/lhoestq/playground/duckdb/m1.txt';
SELECT 'model parquet' AS t, count(*) AS n FROM 'hf://models/lhoestq/playground/duckdb/m1.parquet';
SELECT 'model nested' AS t, count(*) AS n FROM read_parquet('hf://models/lhoestq/playground/duckdb/nested/deep/*.parquet');
SELECT 'model csv' AS t, count(*) AS n FROM 'hf://models/lhoestq/playground/duckdb/m1.csv';
SELECT 'model json' AS t, k FROM 'hf://models/lhoestq/playground/duckdb/m1.json';
SELECT 'model txt' AS t, (SELECT length(content) FROM read_text('hf://models/lhoestq/playground/duckdb/m1.txt')) AS len;
SELECT 'model glob' AS t, count(*) AS n FROM glob('hf://models/lhoestq/playground/duckdb/**/*.parquet');
SELECT 'model ls flat' AS t, count(*) AS n FROM hf_ls('hf://models/lhoestq/playground/duckdb');
SELECT 'model ls deep' AS t, count(*) AS n FROM hf_ls('hf://models/lhoestq/playground/duckdb', recursive := true);
SELECT 'model meta' AS t, size > 0 AS sized, repo_type FROM hf_meta('hf://models/lhoestq/playground/duckdb/m1.parquet');
COPY (SELECT 9 AS v) TO 'hf://models/lhoestq/playground/duckdb/m1.parquet';
SELECT 'model overwrite' AS t, v FROM 'hf://models/lhoestq/playground/duckdb/m1.parquet';
SELECT 'upload blob (LFS)' AS t, size FROM hf_upload('/tmp/hf_model_blob.bin', 'hf://models/lhoestq/playground/duckdb/blob.bin');
SELECT 'upload text (git)' AS t, size FROM hf_upload('/tmp/hf_model_text.txt', 'hf://models/lhoestq/playground/duckdb/m2.txt');
SELECT 'model git file md5' AS t, (SELECT md5(content) FROM read_text('hf://models/lhoestq/playground/duckdb/m2.txt')) = (SELECT md5(content) FROM read_text('/tmp/hf_model_text.txt')) AS match;
SELECT 'model lfs md5' AS t, (SELECT md5(content) FROM read_blob('hf://models/lhoestq/playground/duckdb/blob.bin')) = (SELECT md5(content) FROM read_blob('/tmp/hf_model_blob.bin')) AS match;
SELECT 'model lfs size' AS t, size, exists FROM hf_meta('hf://models/lhoestq/playground/duckdb/blob.bin');
SELECT 'model revisions' AS t, count(*) > 1 AS n FROM hf_list_revisions('hf://models/lhoestq/playground');
SELECT 'model cleanup' AS t, count(*) AS n FROM hf_delete('hf://models/lhoestq/playground/duckdb');
SELECT 'model leftovers' AS t, count(*) AS n FROM hf_ls('hf://models/lhoestq/playground', recursive := true) WHERE path LIKE 'duckdb%';
